import React, { useState, useEffect } from "react";
import "../../styles/MatchingQuestion.css";
import { shuffleArray } from "../../utils/shuffleArray";

const COLORS = ["lightblue", "#fee9be", "#CBC3E3", "#9CAF88", "#FED8B1", "#9bcdff"];

function MatchingQuestion({ question, onSubmit }) {
  const [columns, setColumns] = useState([]);
  const [rowHeaders, setRowHeaders] = useState([]);
  const [options, setOptions] = useState([]);
  const [selections, setSelections] = useState([]);
  const [sets, setSets] = useState([]);
  const [effectiveAnswer, setEffectiveAnswer] = useState([]);

useEffect(() => {
  const correctAnswer = question.correctAnswer;

  // Validate correctAnswer format
  if (!Array.isArray(correctAnswer) || correctAnswer.length === 0 || !Array.isArray(correctAnswer[0])) {
    return;
  }

  const transposed = question.transpose
    ? correctAnswer[0].map((_, colIndex) => correctAnswer.map(row => row[colIndex]))
    : correctAnswer;

  setEffectiveAnswer(transposed);

  const rowCount = transposed.length;
  const colCount = transposed[0].length;

  // If transposed, swap headers
  const columnHeaders = question.transpose
    ? Array.isArray(question.rowHeaders) && question.rowHeaders.length === colCount
      ? question.rowHeaders
      : []
    : Array.isArray(question.columns) && question.columns.length === colCount
      ? question.columns
      : [];

  const rowHeads = question.transpose
    ? Array.isArray(question.columns) && question.columns.length === rowCount
      ? question.columns
      : []
    : Array.isArray(question.rowHeaders) && question.rowHeaders.length === rowCount
      ? question.rowHeaders
      : [];

  setColumns(columnHeaders);
  setRowHeaders(rowHeads);

  // Shuffle options column-wise, but not first column
const newOptions = Array.from({ length: colCount }, (_, colIndex) => {
  const column = transposed.map(row => row[colIndex]);
  return colIndex === 0 ? column : shuffleArray(column);
});

  setOptions(newOptions);
  setSelections(Array(colCount).fill(null));
  setSets([]);
}, [question]);



  const handleSelect = (colIndex, item) => {
    setSelections(prev => {
      const updated = [...prev];
      updated[colIndex] = updated[colIndex] === item ? null : item;
      return updated;
    });
  };

  useEffect(() => {
    if (selections.length === 0) return;
    const allSelected = selections.every(item => item !== null);
    if (!allSelected) return;

    const currentSelections = [...selections];

    setSets(prevSets => {
      const filteredSets = prevSets.filter(
        set => !set.items.some(item => currentSelections.includes(item))
      );

      const usedColors = filteredSets.map(s => s.color);
      const availableColor = COLORS.find(color => !usedColors.includes(color));
      if (!availableColor) return filteredSets;

      return [...filteredSets, { items: currentSelections, color: availableColor }];
    });

    setSelections(Array(selections.length).fill(null));
  }, [selections]);

  const getButtonColor = item => {
    const set = sets.find(set => set.items.includes(item));
    return set ? set.color : "white";
  };

  const handleSubmit = () => {
    const userGroups = sets.map(s => s.items);
    const isCorrect = arraysEqualIgnoringOrder(userGroups, effectiveAnswer);
    onSubmit(userGroups, isCorrect, effectiveAnswer);
  };

  const renderGrid = () => {
    const useColumnMode = columns.length > 0;
    const useRowMode = !useColumnMode && rowHeaders.length > 0;

    const rowCount = effectiveAnswer.length;
    const colCount = effectiveAnswer[0].length;

    return (
      <>
        {/* Column headers */}
        {columns.length > 0 && (
          <>
            {rowHeaders.length > 0 && <div className="matching-cell header" />} {/* top-left corner */}
            {columns.map((header, i) => (
              <div className="matching-cell header" key={`header-${i}`}>{header}</div>
            ))}
          </>
        )}

        {/* Grid */}
        {Array.from({ length: rowCount }).map((_, rowIndex) => (
          <React.Fragment key={`row-${rowIndex}`}>
            {rowHeaders.length > 0 && (
              <div className="matching-cell header" key={`rowheader-${rowIndex}`}>
                {rowHeaders[rowIndex]}
              </div>
            )}
            {Array.from({ length: colCount }).map((_, colIndex) => {
              const item = options[colIndex]?.[rowIndex];
              if (!item) return <div className="matching-cell" key={`cell-${rowIndex}-${colIndex}`} />;

              const selected = selections[colIndex] === item;
              const bg = selected ? "#d0ebff" : getButtonColor(item);

              return (
                <div className="matching-cell" key={`cell-${rowIndex}-${colIndex}`}>
                  <button
                    onClick={() => handleSelect(colIndex, item)}
                    className={`matching-btn${selected ? " selected" : ""}`}
                    style={{ backgroundColor: bg }}
                  >
                    {renderItem(item)}
                  </button>
                </div>
              );
            })}
          </React.Fragment>
        ))}
      </>
    );
  };
const colSpan = effectiveAnswer.length > 0 && Array.isArray(effectiveAnswer[0])
  ? (columns.length || effectiveAnswer[0].length) + (rowHeaders.length > 0 ? 1 : 0)
  : 1;
  
if (!Array.isArray(effectiveAnswer) || effectiveAnswer.length === 0 || !Array.isArray(effectiveAnswer[0])) {
  return <div>Error: Matching question data is not properly formatted.</div>;
}

  return (
    <div
      className="matching-grid"
      style={{ gridTemplateColumns: `repeat(${colSpan}, 1fr)` }}
    >
      {renderGrid()}
      <div className="submit-wrapper" style={{ gridColumn: `span ${colSpan}` }}>
        <button
          onClick={handleSubmit}
          className="submit-btn"
          disabled={sets.length !== effectiveAnswer.length}
        >
          Responder
        </button>
      </div>
    </div>
  );
}

function renderItem(item) {
  if (typeof item === "string" && /\.(png|jpe?g|gif|svg)$/.test(item)) {
    return (
      <img
        src={`${process.env.PUBLIC_URL}/images/${item}`}
        alt=""
        style={{ maxWidth: "80px", maxHeight: "60px", display: "block", margin: "0 auto" }}
      />
    );
  }
  return item;
}

function arraysEqualIgnoringOrder(arr1, arr2) {
  const normalize = arr => arr.map(sub => [...sub].sort().join("|")).sort();
  const norm1 = normalize(arr1);
  const norm2 = normalize(arr2);
  return norm1.length === norm2.length && norm1.every((v, i) => v === norm2[i]);
}

export default MatchingQuestion;
